from typing import Dict, List, Union

from taf.rfrl.procedures.resources.python.bts.components.cell.cell import Cell
from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info, log_debug
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import UnsupportedState
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import DuApi, ApiResponse


class CloudCell(Cell):
    """ Represents Cell created in Cloud RAN. """

    def __init__(self,
                 parent: BtsComponent,
                 cell_info: ApiResponse,
                 api: DuApi,
                 api_alias: str):
        """
        :param parent: BTS component on which this Cell is configured; usually it is Cloud RMOD
        :param cell_info: information about this Cell received as a response to API request;
                          must contain following data:
                          {'dist_names': {'config': 'MRBTS-1/NRBTS-1/NRCELL-1'},
                           'id': '1',
                           'name': 'NRCELL-1',
                           'nr_cell_identity': '138969096',
                           'physical_layer_cell_id': '821',
                           'technology': 'TDD',
                           'nrarfcn': '640000',
                           'nrarfcn_dl': '650000',
                           'nrarfcn_ul': '660000',
                           'channels_mapping': [{'ant_port_id': '1', 'ant_port_name': 'ANT1', 'direction': 'RX',
                                                 'rmod_r_id': '1'},
                                                {'ant_port_id': '2', 'ant_port_name': 'ANT2', 'direction': 'RX',
                                                 'rmod_r_id': '1'}]
        :param api: API used for performing operations on this Cell
        :param api_alias: name of opened API connection which this Cell should use
        """
        log_info('Creating new Cloud Cell')
        super(CloudCell, self).__init__(cell_info['name'], api, api_alias)
        self._parent = parent
        self._id = cell_info['id']
        self._rat = 'NR' if 'NRCELL' in self._name else 'LTE'
        self._technology = cell_info['technology']
        self._config_dist_name = cell_info['dist_names']['config']
        self._nr_cell_identity = cell_info['nr_cell_identity'] if self._rat == 'NR' else None
        self._physical_cell_id = cell_info['physical_layer_cell_id']
        self._nrarfcn = cell_info.get('nrarfcn')
        self._nrarfcn_dl = cell_info.get('nrarfcn_dl')
        self._nrarfcn_ul = cell_info.get('nrarfcn_ul')
        self._channels_mapping = cell_info['channels_mapping']
        log_debug(f'Cloud Cell details:\n'
                  f'name={self._name}\n'
                  f'id={self._id}\n'
                  f'rat={self._rat}\n'
                  f'technology={self._technology}\n'
                  f'config_dist_name={self._config_dist_name}\n'
                  f'nr_cell_identity={self._nr_cell_identity}\n'
                  f'physical_cell_id={self._physical_cell_id}\n'
                  f'nrarfcn={self._nrarfcn}\n'
                  f'nrarfcn_dl={self._nrarfcn_dl}\n'
                  f'nrarfcn_ul={self._nrarfcn_ul}\n'
                  f'channels_mapping={self._channels_mapping}\n'
                  f'parent={self._parent.name}')

    @property
    def rmod(self) -> BtsComponent:
        """ Returns RMOD on which this Cell is configured. """
        return self._parent

    @property
    def id(self) -> str:
        """ Returns ID of this Cell as it is under 'id' key in API response, i.e. '1'.  """
        return self._id

    @property
    def config_dist_name(self) -> str:
        """ Returns configuration dist name of this Cell, i.e. 'MRBTS-1/NRBTS-1/NRCELL-1'. """
        return self._config_dist_name

    @property
    def nr_cell_identity(self) -> Union[str, None]:
        """ Returns NR cell identity of this Cell, i.e. '138969096'. Returns None if RAT is not NR. """
        return self._nr_cell_identity

    @property
    def physical_cell_id(self) -> str:
        """ Returns physical cell ID of this Cell, i.e. '821'. """
        return self._physical_cell_id

    @property
    def nrarfcn(self) -> str:
        """ Returns NRARFCN of this Cell, i.e. '640000'. Returns None if technology is FDD. """
        return self._nrarfcn

    @property
    def nrarfcn_dl(self) -> str:
        """ Returns NRARFCN DL of this Cell, i.e. '640000'. Returns None if technology is TDD. """
        return self._nrarfcn_dl

    @property
    def nrarfcn_ul(self) -> str:
        """ Returns NRARFCN UL of this Cell, i.e. '640000'. Returns None if technology is TDD. """
        return self._nrarfcn_ul

    @property
    def channels_mapping(self) -> List[Dict[str, str]]:
        """
        Returns channels mapping information for this Cell.
        :return: Dictionary with cell mapping details, e.g.:
                 [{'ant_port_id': '1', 'ant_port_name': 'ANT1', 'direction': 'RX', 'rmod_r_id': '1'},
                  {'ant_port_id': '2', 'ant_port_name': 'ANT2', 'direction': 'RX', 'rmod_r_id': '1'},
                  {'ant_port_id': '1', 'ant_port_name': 'ANT1', 'direction': 'TX', 'rmod_r_id': '1'},
                  {'ant_port_id': '2', 'ant_port_name': 'ANT2', 'direction': 'TX', 'rmod_r_id': '1'}]
        """
        return self._channels_mapping

    @pretty_log
    def block(self, timeout: int = 60):
        """
        Blocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed; defaults to 60
        """
        log_info(f'Blocking {self._name} with {timeout}s timeout', to_console=True)
        self._api.block_cell(cell_id=self._id,
                             timeout=timeout,
                             vdu_connection=self._api_alias)

    @pretty_log
    def unblock(self, timeout: int = 60):
        """
        Unblocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed; defaults to 60
        """
        log_info(f'Unblocking {self._name} with {timeout}s timeout', to_console=True)
        self._api.unblock_cell(cell_id=self._id,
                               timeout=timeout,
                               vdu_connection=self._api_alias)

    @pretty_log
    def lock(self, timeout: int = 60):
        """
        Locks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed; defaults to 60
        """
        log_info(f'Locking {self._name} with {timeout}s timeout', to_console=True)
        self._api.lock_cells(cell_id_list=[self._id],
                             timeout=timeout,
                             vdu_connection=self._api_alias)

    @pretty_log
    def unlock(self, timeout: int = 60):
        """
        Unlocks this Cell by sending appropriate API command.
        :param timeout: time (in seconds) in which API command should be executed; defaults to 60
        """
        log_info(f'Unlocking {self._name} with {timeout}s timeout', to_console=True)
        self._api.unlock_cells(cell_id_list=[self._id],
                               timeout=timeout,
                               vdu_connection=self._api_alias)

    def _get_expected_statuses(self, state: str) -> Dict[str, str]:
        expected_statuses = {'NR': {'online': {'procedural_status': 'configured',
                                               'operational_state': 'enabled',
                                               'availability_status': 'on line',
                                               'administrative_state': 'Unlocked',
                                               'blocking_state': 'Unblocked'},
                                    'disabled': {'procedural_status': 'configured',
                                                 'operational_state': 'disabled',
                                                 'availability_status': 'dependency',
                                                 'administrative_state': 'Unlocked',
                                                 'blocking_state': 'Unblocked'},
                                    'blocked': {'procedural_status': 'configured',
                                                'operational_state': 'disabled',
                                                'availability_status': 'off line',
                                                'administrative_state': 'Unlocked',
                                                'blocking_state': 'Blocked'},
                                    'locked': {'procedural_status': 'initialization required',
                                               'operational_state': 'disabled',
                                               'availability_status': 'off line',
                                               'administrative_state': 'Locked',
                                               'blocking_state': 'Unblocked'},
                                    'failed': {'procedural_status': 'not initialized',
                                               'operational_state': 'disabled',
                                               'availability_status': 'failed',
                                               'administrative_state': 'Unlocked',
                                               'blocking_state': 'Unblocked'},
                                    'offline': {'procedural_status': 'configured',
                                                'operational_state': 'disabled',
                                                'availability_status': 'off line',
                                                'administrative_state': 'Unlocked',
                                                'blocking_state': 'Unblocked'}}}

        if state not in expected_statuses[self._rat]:
            raise UnsupportedState(self._UNSUPPORTED_STATE_ERROR_MSG.format(state, self._name))

        return expected_statuses[self._rat][state]

    def _get_current_statuses(self, statuses_names: List[str]) -> Dict[str, str]:
        current_statuses = {}
        cells_info = self._api.get_vdu_cells_status(vdu_connection=self._api_alias)

        for cell_info in cells_info:
            if cell_info['dist_names']['config'] == self._config_dist_name:
                for status_name in statuses_names:
                    current_status_value = cell_info.get(status_name)
                    current_statuses[status_name] = current_status_value

        return current_statuses
